## Code Example
```javascript
// pseudo gate code for Azure Function
module.exports = async function(context, req) {
  const last = new Date(req.fileLastModified);
  const now = new Date();
  if ((now - last) > 24*60*60*1000) throw new Error('Stale file');
  return {status: 'ok'};
};
